<body>
  <main id="app" aria-live="polite"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const api = async (url, options) => {
      const response = await fetch(url, options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    };
    const element = (tag, text, className) => {
      const node = document.createElement(tag);
      if (text !== undefined) node.textContent = text;
      if (className) node.className = className;
      return node;
    };

    async function showProjects() {
      app.replaceChildren();
      app.append(element('h1', 'Workboard'));
      const alert = element('p', '', '');
      alert.setAttribute('role', 'alert');
      app.append(alert);
      const filterWrap = element('div', undefined, 'filter');
      const filterLabel = element('label', 'Project filter');
      filterLabel.htmlFor = 'project-filter';
      const filter = document.createElement('select');
      filter.id = 'project-filter';
      filter.setAttribute('aria-label', 'Project filter');
      for (const value of ['Active', 'Archived']) {
        const option = element('option', value); option.value = value; filter.append(option);
      }
      filterWrap.append(filterLabel, filter);
      app.append(filterWrap);
      const form = document.createElement('form');
      const label = element('label', 'Project name');
      label.htmlFor = 'project-name';
      const input = document.createElement('input');
      input.id = 'project-name';
      input.name = 'name';
      input.type = 'text';
      input.setAttribute('aria-label', 'Project name');
      const submit = element('button', 'Create project');
      submit.type = 'submit';
      form.append(label, input, submit);
      app.append(form);
      const list = element('section');
      list.setAttribute('aria-label', 'Projects');
      app.append(list);
      async function refresh() {
        list.replaceChildren();
        const projects = await api('/api/projects');
        for (const project of projects) {
          if (filter.value === 'Active' && project.archived || filter.value === 'Archived' && !project.archived) continue;
          const row = element('div', undefined, 'project-row');
          row.dataset.testid = 'project-row';
          const name = element('span', project.name, 'project-name');
          name.tabIndex = 0;
          name.title = 'Rename project';
          name.addEventListener('click', () => renameProject(project));
          row.append(name);
          const summary = element('span', `${project.completedCount}/${project.totalCount} completed`, 'project-summary');
          summary.dataset.testid = 'project-summary';
